import SkeletonService from '../../../../../src/services/SkeletonService';
import TableHelper from '../../../../../src/services/TableHelper';
import DataService from '../../../../../src/services/DataService';
import { connectionExists, defaultConnection } from '../../../../../src/config/database';

/**
 * TableCtrl - Laravel TableCtrl.php equivalent
 * Handles AJAX table data requests
 * Auto-generated by ModuleGenerator
 */
export default class TableCtrl {
  /**
   * index method - Main handler
   * @param {Request} req 
   * @param {Response} res 
   * @returns {Promise<Response>}
   */
  async index(req, res) {
    try {
      console.log('🎯 TableCtrl::index() called');

      // Extract and validate token from params (set by SystemRouteController)
      const token = req.params?.token || req.body?.skeleton_token;
      
      if (!token) {
        console.warn('⚠️ TableCtrl: No token provided');
        return res.status(400).json({
      status: false,
          title: 'Token Missing',
          message: 'No token was provided.'
        });
      }

      console.log(`📋 Resolving token: ${token}`);

      // Resolve token configuration
      const reqSet = await SkeletonService.resolveToken(token);

      if (!reqSet || !reqSet.status || !reqSet.key || !reqSet.table) {
        console.error('❌ TableCtrl: Invalid token configuration', reqSet);
        return res.status(400).json({
          status: false,
          title: 'Invalid Token',
          message: 'The provided token is invalid or lacks required configuration.',
          debug: { token, reqSet }
        });
  }

      console.log('✅ Token resolved:', { key: reqSet.key, table: reqSet.table });

      // Set view to table and parse filters
      const draw = parseInt(req.body.draw || 1);
      const filters = req.body.skeleton_filters || {};
      
      // Debug: Log received filters to verify filterType is present
      console.log('📥 Received filters from frontend:', {
        hasColumns: !!filters.columns,
        hasFilterType: !!(filters.filterType || filters.FilterType),
        filterType: filters.filterType || filters.FilterType,
        columnKeys: Object.keys(filters.columns || {})
      });

      // Initialize variables
      let columnList = [];
      let title = '';
      let message = '';

      const normalizedKey = reqSet.key?.endsWith('_t')
        ? reqSet.key.slice(0, -2)
        : reqSet.key;

      // Handle different configuration keys
      switch (normalizedKey) {
        case 'central_filters_master_leads':
          columnList = [
            'id',
            'first_name',
            'last_name',
            'full_name',
            'email',
            'phone',
            'phone1',
            'phone2',
            'company_id',
            'designation',
            'industry',
            'address',
            'address1',
            'address2',
            'address3',
            'address4',
            'city',
            'district',
            'state',
            'pincode',
            'location',
            'website',
            'smtp',
            'need_to_action',
            'source',
            'created_at',
            'updated_at',
            'deleted_at'
          ];
          title = 'Leads Retrieved';
          message = 'Master leads data retrieved successfully.';
          break;

        case 'central_filters_need_to_action':
          columnList = [
            'id',
            'original_collection',
            'original_system',
            'original_id',
            'status',
            'data_preview',
            'modified_fields',
            'created_at',
            'updated_at'
          ];
          title = 'Workspace Records';
          message = 'Need-To-Action workspace records retrieved successfully.';
          break;

        default:
          return res.status(400).json({
            status: false,
            title: 'Invalid Configuration',
            message: 'The configuration key is not supported.'
          });
      }

      // Generate column configuration compatible with TableHelper/DataService
      const columnsConfig = columnList.reduce((acc, col) => {
        acc[col] = [col, true];
        return acc;
      }, {});

      let collectionName = reqSet.table;
      if (normalizedKey === 'central_filters_need_to_action') {
        collectionName = 'need_to_action';
      }

      // Map of collections to their default database connections
      const collectionSystemDefaults = {
        master_leads: 'sun',
        master_accounts: 'sun',
        master: 'sun'
      };
      
      // Determine system to use
      let system = reqSet.system;
      const mappedSystem = collectionSystemDefaults[collectionName];

      if (mappedSystem) {
        if (system && connectionExists(system) && system !== defaultConnection && system !== mappedSystem) {
          console.log(`ℹ️ Using explicit system "${system}" for ${collectionName}`);
        } else {
          if (system !== mappedSystem) {
            console.log(`🔄 Overriding system "${system}" with mapped default "${mappedSystem}" for collection: ${collectionName}`);
          }
          system = mappedSystem;
        }
      } else if (!system || !connectionExists(system)) {
        system = defaultConnection;
        console.log(`⚠️ Invalid or missing system "${reqSet.system}", using default connection: ${system}`);
      }

      console.log(`📊 Using database system: ${system} for collection: ${collectionName}`);

      // Generate params for DataService filter
      const params = TableHelper.generateParams(columnsConfig, [], [], {
        ...reqSet,
        token,
        table: collectionName,
        filters,
        draw,
      });

      // Fetch data using enhanced DataService
      console.log(`📊 Fetching data from ${system} database, collection: ${collectionName}`);
      const dataResponse = await DataService.filter(system, collectionName, params);
      
      console.log(`📊 DataService response:`, {
        status: dataResponse.status,
        dataCount: dataResponse.data?.length || 0,
        recordsTotal: dataResponse.recordsTotal,
        recordsFiltered: dataResponse.recordsFiltered
      });
      
      if (dataResponse.status === false) {
        console.error('❌ DataService returned error:', dataResponse.message);
        return res.status(200).json({
          ...dataResponse,
          title,
          message: dataResponse.message || 'Failed to fetch data',
          columns: [],
          custom: reqSet.custom || [],
          reqSet: {
            ...reqSet,
            token,
            actions: reqSet.actions || 'cevd',
            act: reqSet.act || 'id'
          }
        });
      }
      
      // Transform data based on collection type (like Developer TableCtrl)
      let transformedData = dataResponse.data || [];
      console.log(`🔄 Transforming ${transformedData.length} records for ${reqSet.key}`);
      
      const formatDate = (dateValue) => {
        if (!dateValue) return '';
        if (dateValue instanceof Date) {
          return dateValue.toLocaleString();
        }
        if (typeof dateValue === 'string') {
          try {
            const date = new Date(dateValue);
            if (!isNaN(date.getTime())) {
              return date.toLocaleString();
            }
          } catch (e) {
            console.warn(`⚠️ Failed to parse date: ${dateValue}`, e);
          }
        }
        return '';
      };

      if (normalizedKey === 'central_filters_master_leads') {
        transformedData = transformedData.map((lead, index) => {
          const transformed = {
            id: lead._id ? lead._id.toString() : (lead.id || ''),
            _id: lead._id ? lead._id.toString() : (lead.id || ''),
            first_name: lead.first_name || '',
            last_name: lead.last_name || '',
            full_name: lead.full_name || (lead.first_name && lead.last_name ? `${lead.first_name} ${lead.last_name}`.trim() : ''),
            email: lead.email || '',
            phone: lead.phone || '',
            phone1: lead.phone1 || '',
            phone2: lead.phone2 || '',
            company_id: lead.company_id || '',
            designation: lead.designation || '',
            industry: lead.industry || '',
            address: lead.address || '',
            address1: lead.address1 || '',
            address2: lead.address2 || '',
            address3: lead.address3 || '',
            address4: lead.address4 || '',
            city: lead.city || '',
            district: lead.district || '',
            state: lead.state || '',
            pincode: lead.pincode || '',
            location: lead.location || '',
            website: lead.website || '',
            smtp: lead.smtp || '',
            need_to_action: lead.need_to_action || '',
            source: lead.source || '',
            created_at: formatDate(lead.created_at),
            updated_at: formatDate(lead.updated_at),
            deleted_at: lead.deleted_at || null
          };
          
          if (index === 0) {
            console.log('📋 Sample transformed record:', transformed);
          }
          
          return transformed;
        });
      } else if (normalizedKey === 'central_filters_need_to_action') {
        transformedData = transformedData.map((record, index) => {
          const dataObject = record.data || {};
          const preview = (() => {
            try {
              const json = JSON.stringify(dataObject);
              return json.length > 200 ? `${json.substring(0, 200)}…` : json;
            } catch (error) {
              return '[unserializable data]';
            }
          })();

          const transformed = {
            id: record._id ? record._id.toString() : record.id || '',
            original_id: record.original_id || '',
            original_collection: record.original_collection || '',
            original_system: record.original_system || '',
            status: record.status || 'pending',
            data_preview: preview,
            modified_fields: Array.isArray(record.modified_fields) ? record.modified_fields.join(', ') : '',
            created_at: formatDate(record.created_at),
            updated_at: formatDate(record.updated_at),
            _data: dataObject
          };

          if (index === 0) {
            console.log('📋 Need-To-Action sample record:', transformed);
          }

          return transformed;
        });
      }
      
      console.log(`✅ Transformed ${transformedData.length} records`);

      // Update dataResponse with transformed data
      const updatedDataResponse = {
        ...dataResponse,
        data: transformedData
      };

      // Process response through TableHelper to generate complete table response
      const processedResponse = TableHelper.generateResponse(
        updatedDataResponse,
        columnsConfig,
        reqSet.custom || [],
        {
          ...reqSet,
          token,
          table: collectionName,
          actions: reqSet.actions || 'cevd',
          act: reqSet.act || 'id'
        }
      );

      return res.status(200).json({
        ...processedResponse,
        title,
        message: processedResponse.message || message
      });

  } catch (error) {
      console.error('❌ TableCtrl error:', error);
    return res.status(500).json({
      status: false,
        title: 'Error',
        message: error.message || 'An error occurred while processing the request.'
    });
    }
  }
}
